import * as React from 'react';
import CreateTaskComponent from '../../pages/createTask/components/CreateTaskComponent';
import type { ISpaFeatureProps } from '../../shared/spa/types';

export default function CreateTaskFeature(props: ISpaFeatureProps): React.ReactElement {
  const { pageProps } = props;
  return (
    <CreateTaskComponent
      SelectedProp={pageProps}
      pageContext={pageProps.pageContext}
    />
  );
}

