const CREATE_TASK_INITIAL_SAVE: any = {
    siteType: '',
    linkedServices: [],
    recentClick: undefined,
    Mileage: '',
    DueDate: undefined,
    dueDate: '',
    taskCategory: '',
    taskCategoryParent: '',
    rank: undefined,
    Time: '',
    taskName: '',
    taskUrl: undefined,
    portfolioType: 'Component',
    Component: [],
    Project: {},
    Description: [],
};

const BURGER_QUERY_STOP_PARAMS = [
    'ToolTitle', 'TaskType', 'ComponentID', 'Type', 'ServiceID', 'TeamFeedback', 'TaskAction',
    'TaskId', 'Title', 'siteType', 'TaxType', 'DueDate', 'Priority', 'CreatedBy', 'CreatedDate',
    'Description', 'TaskUrl', 'ExternalSite', 'siteAbsoluteUrl', 'TaskSite', 'Email',
];

function stripBurgerQuerySuffix(raw: string): string {
    if (!raw) {
        return raw;
    }
    let value = raw;
    for (const key of BURGER_QUERY_STOP_PARAMS) {
        const marker = `&${key}=`;
        const idx = value.indexOf(marker);
        if (idx > -1) {
            value = value.slice(0, idx);
        }
    }
    const hashIdx = value.indexOf('#/');
    if (hashIdx > -1) {
        value = value.slice(0, hashIdx);
    }
    return value.trim();
}

function normalizeBurgerTaskUrl(raw: string | undefined): string {
    const trimmed = stripBurgerQuerySuffix((raw || '').trim());
    if (!trimmed || trimmed === 'undefined') {
        return '';
    }
    if (/^https?:?\s*$/i.test(trimmed)) {
        return '';
    }
    if (/^https?:?&/i.test(trimmed)) {
        return '';
    }
    return trimmed;
}

function parseBurgerSiteUrlFromLocation(): string | undefined {
    const completeUrl = window.location.href;
    const siteUrlPart = completeUrl?.split("Siteurl=")[1] || completeUrl?.split("Siteurl")[1];
    if (siteUrlPart) {
        let siteUrlData = siteUrlPart.split('&OR')[0];
        if (siteUrlData.startsWith('=')) {
            siteUrlData = siteUrlData.slice(1);
        }
        if (siteUrlData) {
            try {
                const decoded = decodeURIComponent(siteUrlData);
                const normalized = normalizeBurgerTaskUrl(decoded);
                if (normalized) {
                    return normalized;
                }
            } catch {
                const normalized = normalizeBurgerTaskUrl(siteUrlData);
                if (normalized) {
                    return normalized;
                }
            }
        }
    }

    const params = new URLSearchParams(window.location.search);
    let fromParams = params.get('Siteurl') || undefined;
    if (fromParams && fromParams !== 'undefined' && fromParams !== '') {
        try {
            fromParams = decodeURIComponent(fromParams);
        } catch {
            /* already decoded */
        }
        const normalized = normalizeBurgerTaskUrl(fromParams);
        if (normalized) {
            return normalized;
        }
    }
    return undefined;
}

function resolveBurgerTaskUrl(component: any, rawSiteUrl: string | undefined, pageName?: string, siteBaseUrl?: string): string {
    const normalizedRawSiteUrl = normalizeBurgerTaskUrl(rawSiteUrl);
    if (normalizedRawSiteUrl) {
        return normalizedRawSiteUrl;
    }
    const foundation = component?.FoundationPageUrl;
    if (foundation) {
        const foundationUrl = typeof foundation === 'string'
            ? foundation
            : String(foundation?.Url || foundation?.Description || '');
        if (/^https?:\/\//i.test(foundationUrl)) {
            return foundationUrl;
        }
        const base = (siteBaseUrl || '').replace(/\/$/, '');
        if (base) {
            const path = foundationUrl.startsWith('/') ? foundationUrl : `/${foundationUrl}`;
            return `${base}${path}`;
        }
        return foundationUrl;
    }
    if (pageName && siteBaseUrl) {
        return `${siteBaseUrl.replace(/\/$/, '')}/SitePages/${pageName}`;
    }
    return rawSiteUrl || '';
}

function resolveSiteTypeFromComponent(component: any, sitesTypes: any[]): string {
    if (!component || !sitesTypes?.length) {
        return sitesTypes?.length === 1 ? sitesTypes[0]?.Title || '' : '';
    }

