        (SitesTypes?.length === 1 ? SitesTypes[0].Title : '');
    if (resolvedSiteType) {
        selectedSiteTitle = resolvedSiteType;
    }
    const nextSave = {
        taskName,
        taskUrl,
        siteType: resolvedSiteType,
        rank: '10',
        dueDate: 'Today',
        DueDate: new Date().toISOString(),
    };
    pendingBurgerSave = nextSave;
    pendingBurgerTaskCat = nextTaskCat;
    setSave((prev: any) => ({ ...prev, ...nextSave }));
    setIsActive((prev) => ({
        ...prev,
        siteType: !!resolvedSiteType,
        rank: true,
        dueDate: true,
    }));
    setTaskCat(nextTaskCat);
    setActiveCategory(nextActiveCategory);
    setIsActiveCategory(true);
    setsubCategory([...subCategories]);
    createTask();
};

