const UrlPasteTitle = (e: any) => {
    const testUrl = e?.target?.value ?? '';
    const saveValue = { ...save, taskUrl: testUrl };
    if (SitesTypes?.length > 1) {
        const resolvedSite = testUrl.trim()
            ? resolveSiteTypeFromTaskUrl(testUrl.trim(), SitesTypes)
            : '';
        selectedSiteTitle = resolvedSite;
        saveValue.siteType = resolvedSite;
        setIsActive((prev) => ({ ...prev, siteType: !!resolvedSite }));
    }
    setSave(saveValue);
}

const setActiveTile = (item: keyof typeof save, isActiveItem: keyof typeof isActive, title: any) => {
    let saveItem = save;
    let isActiveData = isActive;
    if (item == 'rank') {
        setIsImmediate(false);
    }
    if (save[item] !== title) {
        saveItem[item] = title;
        setSave(saveItem);
        if (isActive[isActiveItem] !== true) {
            isActiveData[isActiveItem] = true;
            setIsActive(isActiveData);
        }
    } else if (save[item] === title) {
        saveItem[item] = '';
        setSave(saveItem);
        isActiveData[isActiveItem] = false;
        setIsActive(isActiveData);
    }
    if (item === "dueDate") {
        DueDate(title)
    }
    if (item === "Time") {
        setTaskTime(title)
    }
    setSave({ ...save, recentClick: isActiveItem })
};

const selectActiveTaskPriority = (item: keyof typeof save, isActiveItem: keyof typeof isActive, title: any) => {
    let saveItem = save;
    let isActiveData = isActive;

    if (save[item] !== title) {
        saveItem[item] = title;
        setSave(saveItem);
        if (isActive[isActiveItem] !== true) {
            isActiveData[isActiveItem] = true;
            setIsActive(isActiveData);
            setIsImmediate(true);
        }
        else
            setIsImmediate(true);
    }
    else if (save[item] === title) {
        saveItem[item] = '';
        setSave(saveItem);
        isActiveData[isActiveItem] = false;
        setIsImmediate(false);
        setIsActive(isActiveData);
    }
    setSave({ ...save, recentClick: isActiveItem })
};
