React.useEffect(() => {
    ContextValue = props.SelectedProp;
    AllListId = {
        MasterTaskListID: props?.SelectedProp?.MasterTaskListID,
        TaskUserListID: props?.SelectedProp?.TaskUserListID,
        SmartMetadataListID: props?.SelectedProp?.SmartMetadataListID,
        PortFolioTypeID: props?.SelectedProp?.PortFolioTypeID,
        TaskTimeSheetListID: props?.SelectedProp?.TaskTimeSheetListID,
        DocumentsListID: props?.SelectedProp?.DocumentsListID,
        SmartInformationListID: props?.SelectedProp?.SmartInformationListID,
        siteUrl: props?.SelectedProp?.siteUrl,
        AdminConfigrationListID: props?.SelectedProp?.AdminConfigrationListID,
        ColumnManagementListID: props?.SelectedProp?.ColumnManagementListID,
        isShowTimeEntry: isShowTimeEntry,
        Context: props?.SelectedProp?.Context,
        context: props?.SelectedProp?.Context,
        isShowSiteCompostion: isShowSiteCompostion
    };
    let params = new URLSearchParams(window.location.search);
    let teamFeedbackNewpopup = params.get('TeamFeedback') === '1';
    let taskActionNewpopup = params.get('TaskAction') === '1';
    setTeamFeedbackNewpopup(teamFeedbackNewpopup);
    setTaskActionsNewpopup(taskActionNewpopup);
    adminPermision();
    let cancelled = false;
    const boot = async () => {
        setPageLoader(true);
        try {
            const masterPromise = (async () => {
                if (!AllComponents?.length) {
                    const data = await globalCommon.fetchMasterTaskRows();
                    AllComponents = (data || []).filter((itemss: any) => itemss.siteUrl == AllListId?.siteUrl);
                }
            })();
            await Promise.all([GetSmartMetadata(), LoadTaskUsers(), masterPromise]);
            if (cancelled) {
                return;
            }
            metadataReady = true;
            await fetchBurgerMenuDetails();
        } finally {
            if (!cancelled) {
                setPageLoader(false);
            }
        }
    };
    void boot();
    const onSearchChange = () => {
        if (!metadataReady) {
            return;
        }
        void fetchBurgerMenuDetails();
    };
    window.addEventListener('spa-search-change', onSearchChange);
    window.addEventListener('hashchange', onSearchChange);
    return () => {
        cancelled = true;
        window.removeEventListener('spa-search-change', onSearchChange);
        window.removeEventListener('hashchange', onSearchChange);
        clearCreateTaskVisitState();
    };
}, [])
React.useEffect(() => {
    try {
        $("#spPageCanvasContent").removeClass();
        $("#spPageCanvasContent").addClass("hundred");
    } catch (e) {
    }
    AllListId = {
        MasterTaskListID: props?.SelectedProp?.MasterTaskListID,
        TaskUserListID: props?.SelectedProp?.TaskUserListID,
        SmartMetadataListID: props?.SelectedProp?.SmartMetadataListID,
        PortFolioTypeID: props?.SelectedProp?.PortFolioTypeID,
        TaskTimeSheetListID: props?.SelectedProp?.TaskTimeSheetListID,
        DocumentsListID: props?.SelectedProp?.DocumentsListID,
        SmartInformationListID: props?.SelectedProp?.SmartInformationListID,
        siteUrl: props?.SelectedProp?.siteUrl,
        AdminConfigrationListID: props?.SelectedProp?.AdminConfigrationListID,
        ColumnManagementListID: props?.SelectedProp?.ColumnManagementListID,
        isShowTimeEntry: isShowTimeEntry,
        Context: props?.SelectedProp?.Context,
        context: props?.SelectedProp?.Context,
        isShowSiteCompostion: isShowSiteCompostion
    }
    try {
        isShowTimeEntry = props?.SelectedProp?.TimeEntry != "" ? JSON.parse(props?.SelectedProp?.TimeEntry) : "";
        isShowSiteCompostion = props?.SelectedProp?.SiteCompostion != "" ? JSON.parse(props?.SelectedProp?.SiteCompostion) : "";
        AllListId.isShowTimeEntry = isShowTimeEntry;
        AllListId.isShowSiteCompostion = isShowSiteCompostion;
        oldTaskIrl = `${AllListId.siteUrl}/SitePages/CreateTask-old.aspx`
    } catch (error: any) {
        devError(error, "Oops! Something went wrong.");
    }
    base_Url = AllListId?.siteUrl
    pageContext();
    setRefreshPage(!refreshPage);
}, [PageRelevantTask, TaskUrlRelevantTask, ComponentRelevantTask])
React.useEffect(() => {
    if (smartComponentData == undefined || smartComponentData?.length === 0) {
        setSuggestedProjectsOfporfolio([])
    }
}, [smartComponentData])

